  const CBN_SUBJECTS = [{"index":1,"id":"bee-close","title":"Bee Close"},{"index":2,"id":"bees-and-flowers","title":"Bees & Flowers"},{"index":3,"id":"ladybug-daisy","title":"Ladybug Daisy"},{"index":4,"id":"butterfly-sunflower","title":"Butterfly Sunflower"},{"index":5,"id":"grasshopper-grass","title":"Grasshopper"},{"index":6,"id":"hive-close","title":"Hive Close"},{"index":7,"id":"honey-jars","title":"Honey Jars"},{"index":8,"id":"flower-basket","title":"Flower Basket"},{"index":9,"id":"watering-can-tulips","title":"Watering Can"},{"index":10,"id":"greenhouse-rows","title":"Greenhouse Rows"},{"index":11,"id":"meadow-path","title":"Meadow Path"},{"index":12,"id":"bug-net-flowers","title":"Bug Net"}];
  const CBN_EXTRA_EASY = [{"index":13,"id":"one-daisy","title":"One Daisy","stem":"page-13-one-daisy"},{"index":14,"id":"one-honey-jar","title":"One Honey Jar","stem":"page-14-one-honey-jar"},{"index":15,"id":"simple-bee","title":"Simple Bee","stem":"page-15-simple-bee"},{"index":16,"id":"simple-butterfly","title":"Simple Butterfly","stem":"page-16-simple-butterfly"},{"index":17,"id":"simple-ladybug","title":"Simple Ladybug","stem":"page-17-simple-ladybug"},{"index":18,"id":"watering-can-solo","title":"Watering Can","stem":"page-18-watering-can"},{"index":19,"id":"small-hive","title":"Small Hive","stem":"page-19-small-hive"},{"index":20,"id":"one-tulip","title":"One Tulip","stem":"page-20-one-tulip"}];

  function pageIndexById(id) {
    for (let i = 0; i < CBN_PAGES.length; i++) if (CBN_PAGES[i].id === id) return i;
    return -1;
  }

  function pagesForSubject(subject) {
    return CBN_PAGES.filter((p) => p.subject === subject);
  }

  function hitRegion(reg, nx, ny) {
    if (reg.shape === 'rect') {
      return nx >= reg.x && nx <= reg.x + reg.w && ny >= reg.y && ny <= reg.y + reg.h;
    }
    const cx = reg.x, cy = reg.y, rx = (reg.w || 0.1) / 2, ry = (reg.h || 0.1) / 2;
    const dx = (nx - cx) / Math.max(0.001, rx);
    const dy = (ny - cy) / Math.max(0.001, ry);
    return dx * dx + dy * dy <= 1;
  }

  function colorHex(n, page) {
    const k = String(n);
    if (page && page.key && page.key[k]) return page.key[k];
    if (CBN_COLOR_HEX[k]) return CBN_COLOR_HEX[k];
    const i = (n | 0) - 1;
    return (i >= 0 && i < CBN_PALETTE.length) ? CBN_PALETTE[i] : '#cccccc';
  }

  function freshExtras() {
    return {
      flowerPoints: 0,
      bees: 0,
      bugs: { ladybug: 0, grasshopper: 0, butterfly: 0 },
      honey: 0,
      jarsFull: 0,
      jarsEmpty: 8,
      owned: { greenhouse: 0, shovel: 0, sparkle: 0 },
      sparkleUntil: 0,
      cbnDone: [],
      cbnPage: 0,
      cbnFill: {},
      colorRows: 1,
      netMode: 0
    };
  }

  function migrateExtras(raw) {
    const base = freshExtras();
    if (!raw || typeof raw !== 'object') return base;
    const e = Object.assign(base, raw);
    if (!e.bugs || typeof e.bugs !== 'object') e.bugs = { ladybug: 0, grasshopper: 0, butterfly: 0 };
    if (!e.owned || typeof e.owned !== 'object') e.owned = { greenhouse: 0, shovel: 0, sparkle: 0 };
    if (!Array.isArray(e.cbnDone)) e.cbnDone = [];
    if (!e.cbnFill || typeof e.cbnFill !== 'object') e.cbnFill = {};
    const known = Object.create(null);
    CBN_PAGES.forEach((p) => { known[p.id] = 1; });
    e.cbnDone = e.cbnDone.filter((id) => known[id]);
    e.jarsEmpty = Math.max(0, e.jarsEmpty | 0);
    e.jarsFull = Math.max(0, e.jarsFull | 0);
    return e;
  }

  return {
    SHOP, CBN_PALETTE, CBN_COLOR_HEX, CBN_PAGES, CBN_SUBJECTS, CBN_EXTRA_EASY,
    hitRegion, colorHex, pageIndexById, pagesForSubject,
    freshExtras, migrateExtras
  };
